d>										<td class="textcenter">										<a href="{pigcms{:U('User/agent_money_list')}&uid={pigcms{$vo.uid}" >查看佣金</a>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="11">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="11">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script>		 var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('User/export')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>